CREATE POLICY "Staff can upload blog media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'blog-media' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff can update blog media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'blog-media' AND public.is_staff(auth.uid())) WITH CHECK (bucket_id = 'blog-media' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff can delete blog media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'blog-media' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff can read blog media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'blog-media' AND public.is_staff(auth.uid()));